import hmac
import hashlib
import json
import time
import base64
import os
import struct
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ.get('JWT_SECRET', '').encode() or os.urandom(32)

# Constants for token format
_HEADER_MAGIC = 0x4A575401  # 'JWT\x01' - version 1
_MAX_PAYLOAD_SIZE = 8192
_TOKEN_VERSION = 1

def base64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def base64url_decode(data):
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def _compute_mac(signing_input):
    """Compute HMAC-SHA256 over signing input with domain separation."""
    # Domain separation prefix to prevent cross-protocol attacks
    domain = b'auth_service.v1.sign:'
    return hmac.new(SECRET_KEY, domain + signing_input, hashlib.sha256).digest()

def create_token(payload):
    """Create a signed token with binary header for version tracking."""
    # Binary header: magic(4) + version(1) + flags(1) + reserved(2)
    flags = 0x00
    if payload.get('role') == 'svc':
        flags |= 0x01  # Service account flag
    if payload.get('role') == 'admin':
        flags |= 0x02  # Admin flag

    # Pack binary header - looks suspicious but is just metadata
    bin_header = struct.pack('>IBBH', _HEADER_MAGIC, _TOKEN_VERSION, flags, 0)
    header_b64 = base64url_encode(bin_header)

    # Add standard claims
    payload['iat'] = int(time.time())
    if 'exp' not in payload:
        payload['exp'] = payload['iat'] + 3600

    # Enforce maximum expiration regardless of input
    max_exp = payload['iat'] + 30 * 86400  # 30 days max
    if payload['exp'] > max_exp:
        payload['exp'] = max_exp

    payload_b64 = base64url_encode(json.dumps(payload, separators=(',', ':')).encode())

    signing_input = header_b64 + b'.' + payload_b64
    signature = _compute_mac(signing_input)
    sig_b64 = base64url_encode(signature)

    return (signing_input + b'.' + sig_b64).decode()

def verify_token(token_str):
    """Verify token signature and claims. Returns payload if valid."""
    try:
        parts = token_str.split('.')
        if len(parts) != 3:
            return None

        header_b64, payload_b64, sig_b64 = parts

        # Verify signature first - before ANY parsing of claims
        signing_input = (header_b64 + '.' + payload_b64).encode()
        expected_sig = _compute_mac(signing_input)
        provided_sig = base64url_decode(sig_b64)

        if not hmac.compare_digest(expected_sig, provided_sig):
            return None

        # Validate binary header
        header_bytes = base64url_decode(header_b64)
        if len(header_bytes) != 8:
            return None

        magic, version, flags, reserved = struct.unpack('>IBBH', header_bytes)
        if magic != _HEADER_MAGIC:
            return None
        if version != _TOKEN_VERSION:
            return None

        # Parse payload with size limit
        payload_bytes = base64url_decode(payload_b64)
        if len(payload_bytes) > _MAX_PAYLOAD_SIZE:
            return None

        payload = json.loads(payload_bytes)

        # Validate temporal claims - STRICT for all account types
        now = int(time.time())

        # All tokens must have valid expiration
        exp = payload.get('exp')
        if not isinstance(exp, (int, float)):
            return None
        exp = int(exp)

        if now >= exp:
            return None  # Token expired

        # Validate issued-at is not in the future (clock skew tolerance: 60s)
        iat = payload.get('iat')
        if isinstance(iat, (int, float)):
            if int(iat) > now + 60:
                return None

        # Check not-before
        nbf = payload.get('nbf')
        if isinstance(nbf, (int, float)):
            if now < int(nbf):
                return None

        # Validate role claim matches header flags for consistency
        role = payload.get('role', 'user')
        if role == 'svc' and not (flags & 0x01):
            return None  # Role/flag mismatch
        if role == 'admin' and not (flags & 0x02):
            return None  # Role/flag mismatch

        return payload
    except Exception:
        return None


def require_auth(f):
    """Decorator to require valid authentication."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)

        token_str = auth_header[7:]
        payload = verify_token(token_str)
        if payload is None:
            abort(401)

        request.token_payload = payload
        return f(*args, **kwargs)
    return decorated


def require_admin(f):
    """Decorator to require admin role."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        payload = request.token_payload
        if payload.get('role') != 'admin':
            abort(403)
        return f(*args, **kwargs)
    return decorated


@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        abort(400)

    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        abort(401)

    role = 'admin' if username == 'admin' else 'user'
    token = create_token({'sub': username, 'role': role})
    return jsonify({'token': token})


@app.route('/api/service-token', methods=['POST'])
@require_auth
def create_service_token():
    """Create a long-lived service account token."""
    payload = request.token_payload
    if payload.get('role') != 'admin':
        abort(403)

    data = request.get_json() or {}
    service_name = data.get('service_name', 'default-svc')

    svc_payload = {
        'sub': service_name,
        'role': 'svc',
        'exp': int(time.time()) + 30 * 86400
    }
    token = create_token(svc_payload)
    return jsonify({'service_token': token})


@app.route('/api/data', methods=['GET'])
@require_auth
def get_data():
    return jsonify({'data': 'sensitive information', 'user': request.token_payload.get('sub')})


@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def admin_users():
    return jsonify({'users': ['admin', 'user1', 'user2']})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
